/* @component: range-wrap-js */
(function () {
  function initRangeSliders() {
    document.querySelectorAll('.js-range-wrap').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const range = container.querySelector('input[type="range"]');
      const valDisplay = container.querySelector('.range-value');
      if (!range || !valDisplay) return;
      function updateRange() {
        valDisplay.textContent = range.value;
        const min = range.min ? parseFloat(range.min) : 0;
        const max = range.max ? parseFloat(range.max) : 100;
        const val = range.value ? parseFloat(range.value) : 0;
        const pct = ((val - min) / (max - min)) * 100;
        range.style.background = 'linear-gradient(to right, var(--range-accent, #10b981) ' + pct + '%, var(--range-track, #e5e7eb) ' + pct + '%)';
      }
      range.addEventListener('input', updateRange);
      updateRange();
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initRangeSliders);
  } else {
    initRangeSliders();
  }
  setTimeout(initRangeSliders, 300);
})();
/* @end: range-wrap-js */
